css:
.print-format { padding: 0 !important; }
.dacs-walkin { font-family: Arial, sans-serif; font-size: 8pt; margin: 3px 0; padding: 0 6px; text-align: left; }
.dacs-items { width: 100%; font-family: Arial, sans-serif; font-size: 7.5pt; border-collapse: collapse; margin-top: 2px; }
.dacs-items th { font-weight: bold; border-bottom: 1px solid #000; padding: 2px 1px; text-align: center; }
.dacs-items td { padding: 2px 1px; border-bottom: 1px dashed #ccc; vertical-align: top; text-align: center; }
.dacs-items .num { text-align: right; white-space: nowrap; }
